# Tablas aisladas por empresa. `tenant` se filtra por su propio id.
TENANT_TABLES = [
    "app_user",
    "audit_log",
    "email_config",
    "role",
    "tenant_module",
    "tenant_notification_setting",
    "notification",
    "push_subscription",
    "role_permission",
    "user_dashboard",
    "user_notification_preference",
    "user_role",
]
# Sin tenant_id: solo se usan con la sesión de sistema (login y enlaces de email)
SYSTEM_TABLES = ["action_token", "auth_session"]

BYPASS = "current_setting('app.bypass_rls', true) = 'on'"
CURRENT_TENANT = "nullif(current_setting('app.tenant_id', true), '')::uuid"


def enable_tenant_isolation() -> None:
    """Concede permisos al rol de la API y activa Row Level Security."""
    for table in ["tenant", *TENANT_TABLES, *SYSTEM_TABLES]:
        op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON {table} TO konygest_app")
    op.execute(
        f"ALTER TABLE tenant ENABLE ROW LEVEL SECURITY;"
        f"CREATE POLICY tenant_isolation ON tenant USING ({BYPASS} OR id = {CURRENT_TENANT});"
    )
    for table in TENANT_TABLES:
        op.execute(
            f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY;"
            f"CREATE POLICY tenant_isolation ON {table} "
            f"USING ({BYPASS} OR tenant_id = {CURRENT_TENANT});"
        )
    for table in SYSTEM_TABLES:
        op.execute(
            f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY;"
            f"CREATE POLICY system_only ON {table} USING ({BYPASS});"
        )


